CREATE TABLE announcements(id INTEGER PRIMARY KEY AUTOINCREMENT,title TEXT NOT NULL,body TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'draft' CHECK(status IN('draft','published')),published_at INTEGER,created_at INTEGER NOT NULL,updated_at INTEGER NOT NULL);
CREATE TABLE sessions(token_hash TEXT PRIMARY KEY,csrf TEXT NOT NULL,expires INTEGER NOT NULL);
CREATE TABLE login_attempts(id INTEGER PRIMARY KEY AUTOINCREMENT,ip TEXT NOT NULL,ts INTEGER NOT NULL);
CREATE INDEX idx_la ON login_attempts(ip,ts);
CREATE TABLE audit_logs(id INTEGER PRIMARY KEY AUTOINCREMENT,ts INTEGER NOT NULL,action TEXT NOT NULL,detail TEXT);
